import{_ as p,C as s,o as w,c as m,j as t,a,E as o,a8 as g}from"./chunks/framework.27XeWUA0.js";const n="/schedule-dashboard/thumbs/yt/CFbnVpSsDFQ-640.webp",b="/schedule-dashboard/thumbs/yt/CFbnVpSsDFQ-1280.webp",r="/schedule-dashboard/thumbs/yt/bU5gDVyu_28-640.webp",v="/schedule-dashboard/thumbs/yt/bU5gDVyu_28-1280.webp",i="/schedule-dashboard/thumbs/yt/DouK81O8R3o-640.webp",f="/schedule-dashboard/thumbs/yt/DouK81O8R3o-1280.webp",l="/schedule-dashboard/thumbs/yt/uA4ah-dVHvU-640.webp",y="/schedule-dashboard/thumbs/yt/uA4ah-dVHvU-1280.webp",h="/schedule-dashboard/thumbs/yt/YvQ4BVTWfHI-640.webp",k="/schedule-dashboard/thumbs/yt/YvQ4BVTWfHI-1280.webp",c="/schedule-dashboard/thumbs/yt/lyGYidIZK4I-640.webp",_="/schedule-dashboard/thumbs/yt/lyGYidIZK4I-1280.webp",R=JSON.parse('{"title":"AI Digest · Thu 22 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-22","routine":"digest"},"relativePath":"digest/2026-10-22.md","filePath":"digest/[date].md"}'),I={name:"digest/2026-10-22.md"},A=n+" 640w, "+b+" 1280w",V=r+" 640w, "+v+" 1280w",C=i+" 640w, "+f+" 1280w",D=l+" 640w, "+y+" 1280w",x=h+" 640w, "+k+" 1280w",F=c+" 640w, "+_+" 1280w",S={id:"ai-digest-·-thu-22-oct-2026",tabindex:"-1"};function T(H,e,M,O,P,K){const d=s("Badge"),u=s("DayFilter");return w(),m("div",null,[t("h1",S,[e[0]||(e[0]=a("AI Digest · Thu 22 Oct 2026 ",-1)),o(d,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-thu-22-oct-2026","aria-label":'Permalink to "AI Digest · Thu 22 Oct 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack, last 24h (22 Oct 2026) · run date Thu 22 Oct 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer"),a(" posted 5 videos (about 2 hours). The freshest is Sarah Chieng (Cerebras) and Cova Lee (OpenAI) on the agent-run content pipeline behind their 200M views, a long and practical but off-topic creator workflow talk. The two best are Capital One's Max Kanat-Alexander on when code quality still matters (disposable vs durable software) and GEICO's one-day, $1,000-token AI war room for legacy claims code. Vanguard's MCP-for-mainframe-migration talk and MiniMax's speed-vs-accuracy talk lean on well-covered ground (MCP servers, seen 30 times; inference / serving, seen 30 times) but each adds concrete numbers.")]),t("p",null,[t("strong",null,"Better Stack"),a(" posted 1 video: Anatomy, a new agent skill that draws concepts as interactive working machines, fun but slow and token-hungry.")])],-1)),o(u),e[5]||(e[5]=g('<div class="grid cards2"><article class="it full" id="v-CFbnVpSsDFQ" data-title="The AI Content System Behind 200M Views — Sarah Chieng, Cerebras &amp; Cova Lee, OpenAI" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=CFbnVpSsDFQ" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ" target="_blank" rel="noopener">The AI Content System Behind 200M Views — Sarah Chieng, Cerebras &amp; Cova Lee, OpenAI</a></h3><div class="meta">AI Engineer · Sarah Chieng, head of developer experience, Cerebras &amp; Cova Lee, developer experience, OpenAI · uploaded 22 Oct, 4:30 AM IST · 53:18</div><div class="verdict v-skim"><b>Verdict:</b> skim from 5:19 — a practical six-stage playbook with real tools and prompts, but it&#39;s about creator workflow rather than AI engineering, and most of the Q&amp;A is general creator advice.</div><div class="sh">Ideas and scripts</div><ul><li><strong>Swipe files and custom research tools:</strong> Keep every reference you like (a website, Notion, Obsidian) so the agent can learn your taste. Cova had an agent build a YouTube research tool that pulls thousands of videos from creators she likes, plus a fake YouTube homepage to test whether a title and thumbnail stand out. She says about 50% of a video&#39;s performance comes from its packaging, and Sarah says to spend half your time on the title and header image (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=332s" target="_blank" rel="noopener">5:32</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=558s" target="_blank" rel="noopener">9:18</a>)</li><li><strong>Script out loud, then turn it into a skill:</strong> Sarah talks through the idea with Wispr Flow or voice mode (&quot;interview me about it&quot;) so it sounds like teaching, not marketing. She judges posts by engagement compared with similar posts, not raw numbers. A &quot;script skill&quot; built from your past content writes three drafts and scores them, e.g. 50% on engagement (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=573s" target="_blank" rel="noopener">9:33</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=753s" target="_blank" rel="noopener">12:33</a>)</li></ul><div class="sh">Recording, design and editing</div><ul><li><strong>Two-pass shot lists:</strong> The first pass marks the script with A-roll, B-roll, screen recording and graphic cues. The second adds a filming checklist. Coast, an app that works with the Codex CLI and records your screen locally all the time, finds old demos to re-record, and CleanShot handles quick blurs, arrows and notes (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=755s" target="_blank" rel="noopener">12:35</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=930s" target="_blank" rel="noopener">15:30</a>)</li><li><strong>Design systems from fast generation:</strong> Because the Cerebras-powered model in ChatGPT/Codex runs at about 750 tokens/sec, they generate about 10 branding and logo versions and pick the best one. Cova had Codex study her last 50 Instagram videos and write up her recurring visual style as a Figma document <a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=150s" target="_blank" rel="noopener">2:30</a>; (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1026s" target="_blank" rel="noopener">17:06</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1119s" target="_blank" rel="noopener">18:39</a>)</li><li><strong>Editing through APIs and computer use:</strong> HyperFrames (by HeyGen) has an API. You give it raw footage (&quot;stitch these three angles, add text&quot;) and it renders the video, but every change needs a new prompt and a full re-render. HeyGen avatars can patch a half-second slip, like a wrong tokens-per-second figure. For layer-by-layer edits, Astra computer use works on Premiere, and Final Cut has a good MCP. Cova also built a one-click sound-effects pad in one prompt (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1119s" target="_blank" rel="noopener">18:39</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1392s" target="_blank" rel="noopener">23:12</a>)</li><li><strong>Upgrading the set with AI:</strong> Cova first went viral by filling her blank grad-school dorm walls with generated details (Photoshop generative fill then, ChatGPT image generation now). For floating objects, Astra built the models in Blender, exported them as GLB files and placed them in After Effects from a single prompt plus a swipe-file reference (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1392s" target="_blank" rel="noopener">23:12</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1550s" target="_blank" rel="noopener">25:50</a>)</li></ul><div class="sh">Repurposing, publishing and review</div><ul><li><strong>Clips and captions that don&#39;t read as AI:</strong> A long interview takes Sarah about a month, so she cuts it into Shorts, TikToks and Reels. For captions she keeps her own voice separate from the company&#39;s, and pastes Wikipedia&#39;s &quot;Signs of AI writing&quot; article with the instruction to avoid everything in it (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1576s" target="_blank" rel="noopener">26:16</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1677s" target="_blank" rel="noopener">27:57</a>)</li><li><strong>Publishing on autopilot:</strong> ChatGPT sets up the Buffer API from its docs, then posts a folder of cutdowns once a week for six weeks across platforms. It researches the best posting time for each platform and sends her the captions to approve first (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1677s" target="_blank" rel="noopener">27:57</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1759s" target="_blank" rel="noopener">29:19</a>)</li><li><strong>A weekly review skill:</strong> The skill asks &quot;review my video creation process, show me where I spend the most time&quot; and suggests what to automate. It found reminders going to a Slack thread she never reads and a slow Premiere import check that wasn&#39;t needed (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1764s" target="_blank" rel="noopener">29:24</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=1922s" target="_blank" rel="noopener">32:02</a>)</li></ul><div class="sh">Q&amp;A</div><ul><li><strong>Measuring and tuning:</strong> Sarah connected the Twitter API to ChatGPT to A/B test caption styles across cutdowns of the same long video, so the results are a fair comparison. She also had it explain Twitter&#39;s public algorithm repo. Cova&#39;s research tool has a 1x–20x slider for spotting channel outliers (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=2416s" target="_blank" rel="noopener">40:16</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=2503s" target="_blank" rel="noopener">41:43</a>); (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=2994s" target="_blank" rel="noopener">49:54</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=3030s" target="_blank" rel="noopener">50:30</a>)</li><li><strong>Hands-off editing:</strong> Cova says videos go viral when the music, visuals and text all match, so she picks the music first. Sarah has ChatGPT control CapCut on her desktop to fix captions, add sound effects on every transition or image, and enlarge key phrases (<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=2776s" target="_blank" rel="noopener">46:16</a>–<a href="https://www.youtube.com/watch?v=CFbnVpSsDFQ&amp;t=2912s" target="_blank" rel="noopener">48:32</a>)</li></ul></div></article><article class="it full" id="v-bU5gDVyu_28" data-title="Does Code Quality Still Matter? It Depends on This — Max Kanat-Alexander, Capital One" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=bU5gDVyu_28" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+V+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=bU5gDVyu_28" target="_blank" rel="noopener">Does Code Quality Still Matter? It Depends on This — Max Kanat-Alexander, Capital One</a></h3><div class="meta">AI Engineer · Max Kanat-Alexander, Capital One · uploaded 22 Oct, 12:31 AM IST · 16:23</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a short, clear framework for the &quot;does code quality matter with AI&quot; debate. Disposable-vs-durable software is a new angle in the history; only the strict-linting point overlaps earlier talks.</div><div class="sh">Why code quality existed</div><ul><li><strong>Only two things matter:</strong> He says all software success comes down to understanding a system and acting on that understanding. Debuggers, observability, evals, tests and all code-quality work exist only to serve those two things (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=78s" target="_blank" rel="noopener">1:18</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=122s" target="_blank" rel="noopener">2:02</a>)</li><li><strong>Structure is the point:</strong> Using a map of Chromium&#39;s codebase and its URL parser, he argues you can&#39;t describe a big system&#39;s behavior as a whole, only its components. Readability and testability always mattered because they give a system an understandable structure (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=150s" target="_blank" rel="noopener">2:30</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=280s" target="_blank" rel="noopener">4:40</a>)</li><li><strong>Two risks in every change:</strong> Any change can cause a problem (bugs, but also delays or budget overruns) and can make future changes harder. He says he can trace every postmortem he has read back to these two, and they feed each other in a cycle that compounds (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=291s" target="_blank" rel="noopener">4:51</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=394s" target="_blank" rel="noopener">6:34</a>)</li></ul><div class="sh">Disposable vs durable software</div><ul><li><strong>Disposable software is about to dominate:</strong> When the consequences of failure, dependencies, replacement cost and maintenance cost are all near zero, code quality doesn&#39;t matter. He expects such software to become &quot;a hundred thousand times more common&quot;, like your own calculator app or a planner for a single party (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=416s" target="_blank" rel="noopener">6:56</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=549s" target="_blank" rel="noopener">9:09</a>)</li><li><strong>Rigor scales with those four factors:</strong> Durable systems will stay the most important, and AI tools will create more of them. If you&#39;re unsure where a system falls, assume it&#39;s more durable than you think (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=592s" target="_blank" rel="noopener">9:52</a>)</li><li><strong>Make systems more disposable:</strong> Ways to do this include isolated environments with no customer data or PII, a ban on inbound API calls from production systems, a clunky but durable backup so people can vibe-code their own front ends, and narrow scope. He calls this a whole new discipline of software engineering (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=600s" target="_blank" rel="noopener">10:00</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=681s" target="_blank" rel="noopener">11:21</a>)</li></ul><div class="sh">Making rigor cheap</div><ul><li><strong>Standardize and automate the checks:</strong> Standards cut down the options you have to handle (no PHP means no PHP linters or PHP security holes). In-workflow tooling should run on its own, fast and with few false positives, so it&#39;s cheap enough to use even on disposable code (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=725s" target="_blank" rel="noopener">12:05</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=856s" target="_blank" rel="noopener">14:16</a>)</li><li><strong>Easy testing and maximum strictness:</strong> Make every test fast and deterministic without anyone needing to be a testing expert. Coding agents can now build the in-memory fakes of services he always wanted. Set all lint rules to maximum from day one, rather than facing a 100,000-line fix when you turn a linter on in a million-line codebase later (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=859s" target="_blank" rel="noopener">14:19</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=934s" target="_blank" rel="noopener">15:34</a>)</li><li><strong>The answer:</strong> Code quality doesn&#39;t matter for disposable software, does matter for durable software, and doesn&#39;t have to be expensive (<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=950s" target="_blank" rel="noopener">15:50</a>–<a href="https://www.youtube.com/watch?v=bU5gDVyu_28&amp;t=972s" target="_blank" rel="noopener">16:12</a>)</li></ul></div></article><article class="it full" id="v-DouK81O8R3o" data-title="One Day, $1,000 in Tokens: An AI War Room for Legacy Code — Ford Prior, GEICO" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=DouK81O8R3o" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+C+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=DouK81O8R3o" target="_blank" rel="noopener">One Day, $1,000 in Tokens: An AI War Room for Legacy Code — Ford Prior, GEICO</a></h3><div class="meta">AI Engineer · Ford Prior, senior staff engineer &amp; tech evangelist, GEICO claims tech · uploaded 21 Oct, 2:30 PM IST · 18:43</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a concrete enterprise case study with real results, an approach you can copy (FleetKit) and practical lessons on token costs.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 46 times before. New here: agents used for decision-making and legacy-claims modernization rather than everyday coding, run on a one-day, $1,000 token budget.</div><div class="sh">The outer-loop problem</div><ul><li><strong>Coding got fast, everything around it didn&#39;t:</strong> At GEICO, a risk-management company, the build step &quot;has basically been obliterated&quot;, but decisions and sign-offs (the &quot;outer loop&quot;, a Gene Kim term) still hold work back (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=12s" target="_blank" rel="noopener">0:12</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=87s" target="_blank" rel="noopener">1:27</a>)</li><li><strong>25% left for major work:</strong> In a 300-engineer claims group (about 32 teams), engineers had 25% or less of their time for major version work after patches and minor upgrades. GEICO-managed agents now take patch and minor work from spec through to deployment (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=139s" target="_blank" rel="noopener">2:19</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=223s" target="_blank" rel="noopener">3:43</a>)</li></ul><div class="sh">The war room experiment</div><ul><li><strong>Setup and the bet:</strong> The room holds the key decision makers and experts, one driver running the AI tools, a comms channel, a design studio and the code repos, all wired to skills, MCPs and agent fleets. The bet: with $1,000 in tokens and one day, map a legacy claims domain of millions of lines end to end and have an agent-callable API deployed for a 4 PM demo (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=278s" target="_blank" rel="noopener">4:38</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=383s" target="_blank" rel="noopener">6:23</a>)</li><li><strong>Three runs:</strong> He ran it three times, using the uplift / transform / reimagine taxonomy from Anthropic&#39;s code modernization plugin. Rentals: an existing API was extended and the agent found a way to save 8,500 calls a month. Damages: new agent-callable APIs. Salvage: a fully vetted migration plan with API specs and mock-ups that product and tech approved, and it also turned up a production bug (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=388s" target="_blank" rel="noopener">6:28</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=503s" target="_blank" rel="noopener">8:23</a>)</li><li><strong>Vendor vs GEICO:</strong> The harness, model, FleetKit and plugin could be swapped for another vendor&#39;s. What couldn&#39;t be swapped was GEICO&#39;s context (standards, the history of past decisions), tool list, methods (skills) and judgment (who can approve what, at which gate), kept in repos that both agents and humans edit (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=509s" target="_blank" rel="noopener">8:29</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=578s" target="_blank" rel="noopener">9:38</a>)</li></ul><div class="sh">FleetKit and the artifacts</div><ul><li><strong>FleetKit:</strong> A set of rules and protocols in markdown, built with Anthropic and not yet open source. It breaks a goal into parts, sends leader agents to do research, puts decisions in a queue for human approval (GitHub issues would work) and then sends builder agents, using beads to keep track of work. He thinks only &quot;Opus 48&quot; (as captioned) and later models can handle this level of steering (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=587s" target="_blank" rel="noopener">9:47</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=690s" target="_blank" rel="noopener">11:30</a>)</li><li><strong>Worksheets and diagrams:</strong> Each mission gets a Slack-style channel, and the agent tags specific people from the roster when it&#39;s missing details. At each milestone it produces HTML worksheets with autosave, or architecture diagrams that people edit and the agent reads back. He says its questions caught edge cases nobody had considered, and teams kept the diagrams (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=722s" target="_blank" rel="noopener">12:02</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=838s" target="_blank" rel="noopener">13:58</a>)</li><li><strong>Cloud code-dives plus a local runtime:</strong> Cloud agents analyzed the legacy domain-specific languages. Local agents on his laptop, the runtime for the nine steps, used enterprise MCPs through a bindings file. The plugin also checks deterministically that each step produced the files it needed (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=846s" target="_blank" rel="noopener">14:06</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=956s" target="_blank" rel="noopener">15:56</a>)</li></ul><div class="sh">Lessons</div><ul><li><strong>Costs and models:</strong> Don&#39;t let the agent set up crons to check on work, because each check starts a new session and burns the budget. Prompt caching mattered far more than he expected. In benchmarks against recently written code, Sonnet 5.5 wrote legacy code as well as or better than the larger model (&quot;Fable&quot;, as captioned). His conclusion: &quot;model selection for the win&quot; (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=958s" target="_blank" rel="noopener">15:58</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=1008s" target="_blank" rel="noopener">16:48</a>)</li><li><strong>Next:</strong> Stricter enforcement of approval gates, decision models in the harness, better search over the plain-markdown context, and recording meetings as a data source instead of taking notes by hand (<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=1008s" target="_blank" rel="noopener">16:48</a>–<a href="https://www.youtube.com/watch?v=DouK81O8R3o&amp;t=1071s" target="_blank" rel="noopener">17:51</a>)</li></ul></div></article><article class="it full" id="v-uA4ah-dVHvU" data-title="AI Cut Our Research Time From 7 Days to 15 Minutes — Gareth Yoder, Vanguard" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=uA4ah-dVHvU" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+D+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=uA4ah-dVHvU" target="_blank" rel="noopener">AI Cut Our Research Time From 7 Days to 15 Minutes — Gareth Yoder, Vanguard</a></h3><div class="meta">AI Engineer · Gareth Yoder, cash program technical lead, Vanguard · uploaded 21 Oct, 1:30 PM IST · 15:39</div><div class="verdict v-skim"><b>Verdict:</b> skim from 2:32 — the 7-days-to-15-minutes MCP point is useful, but most of the talk is standard migration architecture.</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 30 times before. New here: MCP used to expose a mainframe-era legacy codebase and migration docs during a bank-scale ledger migration.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 11 times before. New here: a concrete Vanguard cash-ledger modernization story rather than a general pitch.</div><div class="sh">The system and the MCP turning point</div><ul><li><strong>What&#39;s being migrated:</strong> Vanguard&#39;s cash ledger handles all money movement into and between brokerage accounts (ACH, wires) across web, mobile and batch, runs active-active multi-region, takes up to 30 million calls a day and creates half a million ledgers daily (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=70s" target="_blank" rel="noopener">1:10</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=112s" target="_blank" rel="noopener">1:52</a>)</li><li><strong>Legacy code over MCP:</strong> Data, producer and consumer migrations ran in parallel; once the legacy codebase was exposed to AI tools via an MCP server, schema research that took a mainframe engineer 7 days became a 15-minute prompt (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=112s" target="_blank" rel="noopener">1:52</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=198s" target="_blank" rel="noopener">3:18</a>)</li></ul><div class="sh">How the three migrations worked</div><ul><li><strong>Data:</strong> Standard change data capture, with daily audits checking row counts and then column-level matches (amounts, account info, state and federal withholding); the tip is not to over-engineer code that gets deprecated (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=200s" target="_blank" rel="noopener">3:20</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=251s" target="_blank" rel="noopener">4:11</a>)</li><li><strong>Producers:</strong> Legacy writes came via service requests, a wrapping API and untraceable direct table inserts; the new gateway added idempotency and Snowflake-ID-style ordering, and putting the docs for 35 producers behind the MCP server sharply cut support chats (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=251s" target="_blank" rel="noopener">4:11</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=392s" target="_blank" rel="noopener">6:32</a>)</li><li><strong>Consumers:</strong> Real-time GraphQL (e.g. funds available), per-consumer data-share views in the warehouse for batch, and a Kafka stream with at-least-once delivery and idempotent retries used by fraud teams (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=398s" target="_blank" rel="noopener">6:38</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=532s" target="_blank" rel="noopener">8:52</a>)</li><li><strong>Business justification per consumer:</strong> All 50 consumers had to give a use-case description, so AI can summarize what&#39;s been modernized and how urgent an SLA breach is (hours for batch, minutes for real-time APIs) (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=537s" target="_blank" rel="noopener">8:57</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=661s" target="_blank" rel="noopener">11:01</a>)</li></ul><div class="sh">Lessons</div><ul><li><strong>AI use today:</strong> 90% of the cash program&#39;s engineers use AI tools daily, with multi-agent workflows and a shared &quot;team brain&quot; knowledge base that gives a new hire the same prompt context as a 5-year veteran; fix forward in the new system rather than patching the old (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=672s" target="_blank" rel="noopener">11:12</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=790s" target="_blank" rel="noopener">13:10</a>)</li><li><strong>Five takeaways:</strong> Make legacy code AI-queryable, treat migration docs as product, reimagine instead of lift-and-shift (lift-and-shift teams were hardest to onboard), adopt AI incrementally, and observability is non-negotiable (<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=792s" target="_blank" rel="noopener">13:12</a>–<a href="https://www.youtube.com/watch?v=uA4ah-dVHvU&amp;t=915s" target="_blank" rel="noopener">15:15</a>)</li></ul></div></article><article class="it full" id="v-YvQ4BVTWfHI" data-title="Is a Faster Model Actually Faster? Test the Whole Job — Morgan Suo, MiniMax" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=YvQ4BVTWfHI" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI" target="_blank" rel="noopener">Is a Faster Model Actually Faster? Test the Whole Job — Morgan Suo, MiniMax</a></h3><div class="meta">AI Engineer · Morgan Suo, MiniMax · uploaded 21 Oct, 12:30 PM IST · 17:43</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:53 — the KV-cache, concurrency and reasoning-budget numbers are concrete; the rest repeats well-covered inference ground, and the recap is a MiniMax video-model demo.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 30 times before (including speculative-decoding and KV-cache talks from Akamai and FriendliAI). New here: how each speed trick in MiniMax M3.1 Flash can quietly cost accuracy or wait time.</div><div class="repeat">🔁 Repeat: &#39;LLM releases / benchmarks&#39; — seen 37 times before. New here: a first look at M3.1 Flash, which she says is due next week, and why average scores can hide the errors users care about.</div><div class="sh">The test job</div><ul><li><strong>One real research task:</strong> An analyst asks whether circuit-board (PCB) suppliers are turning AI server demand into cash, across 14 company reports; a usable report lets the analyst open sources, check calculations and see what could change the conclusion (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=104s" target="_blank" rel="noopener">1:44</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=199s" target="_blank" rel="noopener">3:19</a>)</li><li><strong>Profit vs cash:</strong> Profit can rise while customers haven&#39;t paid or materials sit in storage, so the model has to point to the cash flow statement and disclosures (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=202s" target="_blank" rel="noopener">3:22</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=261s" target="_blank" rel="noopener">4:21</a>)</li></ul><div class="sh">What changed inside M3.1 Flash</div><ul><li><strong>Sparse attention on long inputs:</strong> A small step scores text blocks and main attention uses only the selected ones (plus nearby text); in a long-input retrieval test the model passed all 39 requests with inputs up to about 830k tokens, but a short footnote can still flip a cash-flow conclusion (repeat) (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=315s" target="_blank" rel="noopener">5:15</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=472s" target="_blank" rel="noopener">7:52</a>)</li><li><strong>4-bit KV cache:</strong> Keys and values drop from 8 to 4 bits (queries stay 8-bit); the average score barely moved, but one score fell 6.6 points, so averages can hide the mistake a user cares about (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=478s" target="_blank" rel="noopener">7:58</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=537s" target="_blank" rel="noopener">8:57</a>)</li><li><strong>Low-precision experts and speculative decoding:</strong> Selected MoE experts use 4-bit weights and activations (the shared expert doesn&#39;t), and where the scale is restored matters; with speculative decoding, count drafting, checking and rejection time too (repeat) (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=539s" target="_blank" rel="noopener">8:59</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=702s" target="_blank" rel="noopener">11:42</a>)</li></ul><div class="sh">Serving and reasoning settings</div><ul><li><strong>Throughput vs wait time:</strong> Going from 32 to 64 concurrent requests raised total output per second about 1.9x, but P95 time to first token went from about 1.5 s to about 11.3 s, roughly 8x longer (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=707s" target="_blank" rel="noopener">11:47</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=786s" target="_blank" rel="noopener">13:06</a>)</li><li><strong>Reasoning budgets:</strong> Leaving effort blank defaults to max; on a coding test, &quot;high&quot; used fewer output tokens than &quot;max&quot; but accuracy fell from 80% to 68% (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=790s" target="_blank" rel="noopener">13:10</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=877s" target="_blank" rel="noopener">14:37</a>)</li><li><strong>How to judge a switch:</strong> Fix the sources and information cutoff, then check three things: can the analyst trust it, what the finished job cost (retrieval, tool calls, retries, human fixes, failed attempts) at real user load, and can it be repeated (save model, runtime, prompt and source versions; roll out small with a way back) (<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=881s" target="_blank" rel="noopener">14:41</a>–<a href="https://www.youtube.com/watch?v=YvQ4BVTWfHI&amp;t=969s" target="_blank" rel="noopener">16:09</a>)</li></ul></div></article><article class="it full" id="v-lyGYidIZK4I" data-title="AI Just Made Physics Interactive. This Is Insane. (Anatomy)" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=lyGYidIZK4I" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+F+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=lyGYidIZK4I" target="_blank" rel="noopener">AI Just Made Physics Interactive. This Is Insane. (Anatomy)</a></h3><div class="meta">Better Stack · Josh, Better Stack · uploaded 21 Oct, 5:30 PM IST · 5:56</div><div class="verdict v-skim"><b>Verdict:</b> skim — fun demos, but the 30-minute-plus render times make it a niche tool for docs and teaching.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 9 times before. New here: a skill that draws working &quot;machines&quot; instead of diagrams.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 6 times before. New here: figures that take 30 minutes to hours, sometimes over 48 hours, to render.</div><div class="sh">What Anatomy is</div><ul><li><strong>Machines, not boxes and arrows:</strong> Anatomy is a new Claude skill whose rule is to invent a physical machine that works like your concept, e.g. a pin tumbler lock for a cache key, a running LRU cache, and a TCP handshake as letters sent on a rope; the repo also ships a Raptor engine with a WebGL exhaust plume (<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=91s" target="_blank" rel="noopener">1:31</a>)</li><li><strong>How it works:</strong> It&#39;s a SKILL.md plus a drawing kit (isometric camera, solids, tubes, optional WebGL, 3D in beta) with zero dependencies on Node 20.10+; it runs in Claude Code, Codex, OpenCode and Antigravity and outputs standalone HTML, SVG or a React component (<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=124s" target="_blank" rel="noopener">2:04</a>–<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=164s" target="_blank" rel="noopener">2:44</a>)</li><li><strong>Truth first:</strong> It first collects real numbers and builds a small model of how the thing behaves, wires the on-screen readout to it, then opens Chrome to check its own geometry; his database connection pooling demo lets you change speed and scenarios (<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=168s" target="_blank" rel="noopener">2:48</a>–<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=247s" target="_blank" rel="noopener">4:07</a>)</li></ul><div class="sh">The catch</div><ul><li><strong>Very slow and token-hungry:</strong> A normal figure takes 30–90 minutes and a hero piece 2–4 hours; the maintainer said in a GitHub issue that some renders take over 48 hours and burn all your tokens (<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=249s" target="_blank" rel="noopener">4:09</a>–<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=279s" target="_blank" rel="noopener">4:39</a>)</li><li><strong>Checks the picture, not the facts:</strong> Claude is good at building these but not at seeing them, and the self-checks only test geometry, so the explanation is only as true as the invented analogy; he says it&#39;s for people who write docs or teach, if they have the tokens (<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=281s" target="_blank" rel="noopener">4:41</a>–<a href="https://www.youtube.com/watch?v=lyGYidIZK4I&amp;t=346s" target="_blank" rel="noopener">5:46</a>)</li></ul></div></article></div>',1))])}const q=p(I,[["render",T]]);export{R as __pageData,q as default};
